# ---------- 剥离上一档尾随分隔线（§3.126b：避免空分隔块） ----------
src = open(P, encoding='utf-8').read()
h_before = hashlib.md5(src.encode('utf-8')).hexdigest()
body = src.rstrip()
while body.endswith('---'):
    body = body[:-3].rstrip()
lines_before = src.count('\n') + 1
head = body.split('\n')
assert head[0].startswith('# WealthHub 日报'), head[0]

new = body + '\n\n' + CH.rstrip() + '\n'
open(P, 'w', encoding='utf-8').write(new)
h_after = hashlib.md5(open(P, encoding='utf-8').read().encode('utf-8')).hexdigest()

# ---------- 质检（§3.100 / §3.106 / §3.129e） ----------
txt = open(P, encoding='utf-8').read()
sec = [l for l in txt.split('\n') if l.startswith('## ')]
n_ph = len(re.findall(r'@[A-Z_0-9]+@', txt))
n_dup = txt.count('元' + '[双后缀占位]') + len(re.findall(r'元\s+元', txt))
n_sep = len(re.findall(r'^---\s*\n\s*\n---', txt, re.M))
print('=== 质检 ===')
print(f'  章节数 = {len(sec)} → {[s[:34] for s in sec]}')
print(f'  占位符 = {n_ph}')
print(f'  单位重复后缀（描述性计数）= {n_dup}')
print(f'  连续分隔块 = {n_sep}')
print(f'  盘前章节（行 1..{lines_before}）未改动 = {new.startswith(src.rstrip())}')
assert len(sec) == 2, f'章节数应为 2，实为 {len(sec)}'
assert n_ph == 0, '存在未替换占位符'
assert n_dup == 0, '存在单位重复后缀'
assert n_sep == 0, '存在连续分隔块'
assert new.startswith(src.rstrip()), '盘前章节被改动'
print(f'\nmd5 前 = {h_before[:12]}  后 = {h_after[:12]}')
print(f'总行数 {new.count(chr(10)) + 1}')
print('已追加「二、盘中调仓建议（13:45 档）」')
